#!/usr/bin/env python3
"""Build one indexable page per medical-lab demo: /medical-ai/lab/<slug>/index.html.

Same pattern as build_lab_pages.py (the audio lab). The demo markup is copied from the hub
(/medical-ai/lab/index.html), so the hub stays the single source for each experiment. Edit an
experiment there, then re-run:

    python3 _tools/lab-pages/build_medical_lab_pages.py

The shared JS (assets/medical-lab.js, plus assets/c-medical.js for the ECG demo) wires up only the
experiments whose section is on the page, so each page carries exactly one section.
Page-specific copy (title, description, answer-first paragraph, one-line summary, explainer) lives in PAGES
below; the worked example, checklist and FAQ for each page live in EXTRA. The first three FAQ entries use the
phrasing people type into search engines and AI assistants. Bump DATE_MODIFIED (or a page's own "modified") when the copy changes. Share images are
assets/og/lab-<slug>.png, rendered by _tools/share-images/make_cards.py.

Content rules: synthetic data only, plain technical English, no client or hospital names, no
performance claims about real projects.
"""
import datetime
import html
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
HUB = ROOT / "medical-ai" / "lab" / "index.html"
SITE = "https://www.mlaia.com"
DATE_PUBLISHED = "2026-11-03"
DATE_MODIFIED = "2026-11-10"


def dates(p):
    """(datePublished, dateModified, visible label). A page can override the defaults with "published" / "modified"."""
    pub, mod = p.get("published", DATE_PUBLISHED), p.get("modified", DATE_MODIFIED)
    d = datetime.date.fromisoformat(mod)
    return pub, mod, f"Updated {d.strftime('%B')} {d.day}, {d.year}"
